# Keep every photograph even when the supplied archive expands.
for f in sorted((ROOT/'assets/photography').glob('*.jpg')):
 PHOTO.setdefault(f.stem,('From the field','Photograph from the supplied Dreamer archive','Wildlife'))
DERIV={}
for f in sorted((ROOT/'assets').rglob('*')):
 if f.suffix.lower() not in ('.jpg','.png','.webp') or 'editorial' in f.parts:continue
 im=ImageOps.exif_transpose(Image.open(f)).convert('RGB'); rel=f.relative_to(ROOT).as_posix();w,h=im.size
 variants=[]
 for width in sorted(set([min(w,480),min(w,960),min(w,1600)])):
  dest=ROOT/'assets/editorial'/f.relative_to(ROOT/'assets').with_suffix('')
  dest=Path(str(dest)+f'-{width}.webp');dest.parent.mkdir(parents=True,exist_ok=True)
  if not dest.exists():im.resize((width,round(h*width/w)),Image.Resampling.LANCZOS).save(dest,'WEBP',quality=85)
  variants.append((width,dest.relative_to(ROOT).as_posix()))
 DERIV[rel]=(w,h,variants)

def img(path,alt,cls='',eager=False):
 w,h,v=DERIV[path];src=v[-1][1];srcset=', '.join('/'+s+' '+str(n)+'w' for n,s in v)
 return f'<img class="{cls}" src="/{src}" srcset="{srcset}" sizes="(max-width: 760px) 92vw, 70vw" width="{w}" height="{h}" alt="{e(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def figure(path,caption,alt=None,cls=''):
 return f'<figure class="{cls}">{img(path,alt or caption)}<figcaption>{e(caption)}</figcaption></figure>'
def link(url,label,cls='text-link'):
 return f'<a class="{cls}" href="{url}">{label} <span aria-hidden="true">↗</span></a>'
def label(text):return '<span class="eyebrow">'+e(text)+'</span>'
def video(path,poster,caption,auto=False):
 if auto:
  el=f'<video data-ambient data-src="/{path}" muted loop playsinline preload="none" poster="/{poster}" aria-label="{e(caption)}"></video><button class="video-pause" data-pause aria-label="Play background film">Play film</button>'
 else:el=f'<video controls playsinline preload="none" poster="/{poster}" aria-label="{e(caption)}"><source src="/{path}" type="video/mp4"></video>'
 return f'<figure class="local-film">{el}<figcaption>{e(caption)}</figcaption></figure>'
STORIES=[
{'slug':'wildlife-wonders','title':'A world worth looking closer at.','category':'WILDLIFE / CONSERVATION','place':'Tunisia','image':P('556922215'),'desc':'From the smallest encounter to the wider landscape, Wildlife Wonders brings Tunisia’s natural heritage into view.','film':'oBRHiGLC0S4','credit':'The Dreamer × Zakher Bouragaoui · Tunisian Wonders','images':[P('555630946'),P('700708021'),P('556626056')], 'chapters':[('The living world, close up.','An owl in the shelter of stone. A reptile resting in sunlight. A bird in flight. Small encounters are a reminder that a landscape is more than its scenery. The camera gives those lives time and space within the frame.'),('A story made in the field.','Rabii describes working with wildlife ecologist Zakher Bouragaoui through the Tunisian Wonders initiative. The resulting film, Wildlife Wonders, follows a purpose central to The Dreamer: bringing Tunisia’s natural heritage into view.'),('Attention is a beginning.','The film connects visual storytelling with an interest in the living world. Its contribution here is an invitation to notice, to learn and to look again. No numerical conservation outcome is claimed for this project.')], 'source':'https://www.linkedin.com/posts/rabii-ben-brahim-007309141_wildlife-wonders-activity-7311423928600596482-iWgy'},
{'slug':'blue-future','title':'The sea connects the stories.','category':'DOCUMENTARY / CONSERVATION','place':'Mediterranean','image':P('526506341'),'desc':'A shared sea, different livelihoods. Blue Future follows work and lives tied to the Mediterranean.','film':'OyaSu8oF-D8','credit':'WWF / COGITO · Ante Gugić, Rabii Ben Brahim, Emanuele Quartarone and Beatrice Surano','images':[P('651451626'),P('650345189'),P('526763980')],'clip':'assets/projects/coastal-voices.mp4','poster':'assets/projects/coastal-voices.jpg', 'chapters':[('More than a horizon.','Seen from above, the coast becomes a meeting of rock, shallows and deep water. Seen from shore, it is also a place of work, knowledge and daily routines. These supplied photographs give the sea a human scale.'),('Three perspectives, one sea.','Blue Future is a collective documentary about sustainable livelihoods around the Mediterranean. WWF and COGITO are credited in its production. Rabii Ben Brahim appears among the four filmmaker credits, alongside Ante Gugić, Emanuele Quartarone and Beatrice Surano.'),('People belong in the frame.','The documentary’s environmental context includes the people whose work is connected to the sea. The coastal footage and photographs on this page extend that theme; they are selected from the supplied archive and are not presented as verified production stills from Blue Future.')], 'source':'https://www.wwf.it/area-stampa/blue-future-il-documentario-wwf-sui-lavori-blu/'},
{'slug':'djerba-between-sea-and-stone','title':'Between sea & stone.','category':'EXPEDITION / PHOTOGRAPHIC ESSAY','place':'Djerba, Tunisia','image':D('03-coastal-courtyard'),'desc':'Whitewashed courtyards, blue doorways and a filming day by the coast. A journey through the supplied Djerba field archive.','credit':'Field film and photographs supplied by The Dreamer','images':[D('02-blue-door'),D('04-rabii-filming'),D('07-team')],'clip':'assets/projects/djerba/coastline.mp4','poster':'assets/projects/djerba/03-coastal-courtyard.webp','chapters':[('A place in the details.','The visual story begins in the architecture: the curve of a courtyard, bright walls under open sky, and the blue of a weathered doorway. Together, these details hold a sense of place without needing a grand panorama.'),('On the other side of the camera.','The field photographs bring the filmmaking process into view. Rabii works with a camera, people gather for conversation, and the crew shares the space around them. The story of a place is also the story of meeting it.'),('The coast keeps moving.','A short coastal film gives the still photographs another rhythm. The supplied material is presented as a field essay, rather than a claim about a commissioned campaign or measurable conservation outcome.')], 'extra':[D('01-seaside-portrait'),D('05-interview'),D('06-land-rover'),D('08-camera-and-guest')]},
{'slug':'the-defender-journey','title':'The road is part of the story.','category':'COLLABORATION / EXPLORATION','place':'Tunisia','image':'assets/projects/defender-field.jpg','desc':'A journey across Tunisia for the Land Rover Defender campaign, with The Dreamer at the centre of the film.','film':'YkmgKAZFtXs','credit':'Land Rover Defender campaign · YKONE Tunis','images':['assets/about/01.jpg','assets/about/09.jpg','assets/projects/road-expedition.jpg'],'clip':'assets/projects/defender-field.mp4','poster':'assets/projects/defender-field.jpg','chapters':[('A different way to travel.','The road links coast, dunes and open ground. In this campaign, the journey is the setting for Rabii’s identity as The Dreamer: someone drawn to exploration and the places beyond the familiar view.'),('Exploration in context.','YKONE’s published case study identifies the Land Rover Defender campaign. The existing site connects the work with a road trip across Tunisia. The local clip shown here is supplied field footage, distinct from the linked campaign film.'),('Making room for the landscape.','Vehicle, traveller and place share the frame. The strongest moments let the surroundings carry the story: an open road, a pause beside the vehicle and another stretch of country ahead.')],'source':'https://ykone.com/portfolio/landrover-defender/'},
{'slug':'a-country-in-motion','title':'A country in motion.','category':'FILM / LANDSCAPE','place':'Tunisia','image':'assets/frames/tunisia-02.jpg','desc':'From forest to coast and open country: a cinematic journey through Tunisia.','film':'OtJVufo3IrA','credit':'The Dreamer · Tunisia film. Landscape images are frames from the supplied film.','images':['assets/frames/tunisia-06.jpg','assets/frames/tunisia-09.jpg','assets/frames/tunisia-14.jpg'],'chapters':[('Follow the landscape.','The Tunisia film moves between wide vistas and the details that make them particular. Its landscape frames are gathered here as a visual essay, keeping the distinction between moving-image stills and standalone photography clear.'),('Let the image breathe.','A coastline, a hillside and the light across open ground each ask for a different pace. In the film, movement links those views. On the page, space between the images lets each one stand on its own.'),('Another way to see home.','Tunisia remains at the heart of The Dreamer’s work. The journey is an invitation to discover the country through its landscape, its living world and the people connected to it.')]},
{'slug':'a-different-way-of-seeing','title':'A different way of seeing.','category':'COMMUNITY / PHOTOGRAPHY','place':'Tunisia','image':'assets/impact/field-mentoring.webp','desc':'Sharing the camera, sharing attention. Photography becomes a meeting point between people and place.','credit':'Supplied community footage and photography · CinémaJet, Zaghouan activity listed in the existing project archive','images':['assets/impact/photography-workshop.webp','assets/projects/community-field.jpg','assets/projects/cinemajet.jpg'],'clip':'assets/projects/community-field.mp4','poster':'assets/projects/community-field.jpg','chapters':[('The camera can be a meeting point.','In the supplied photographs, participants gather around the process of making an image. Watching, talking and taking turns become part of the story. The camera is a practical way to share attention.'),('A place through its people.','The existing project archive describes Rabii’s participation in the CinémaJet photography programme in Zaghouan. The activity invites a view of the city through the residents who give it life.'),('Beyond a finished photograph.','The images on this page document conversation and participation. They show a process, rather than a quantified impact claim. The relationships around the frame matter alongside the photograph itself.')]}]
