def doc(route,title,desc,body,image='assets/hero-new/poster.webp',article=False):
 nav=''.join(f'<a href="/{slug}/"'+(' aria-current="page"' if route.strip('/').split('/')[0]==slug else '')+f'>{name}</a>' for name,slug in NAV)
 secondary=''.join(link('/'+slug+'/',name,'') for name,slug in SECOND)
 schema={'@context':'https://schema.org','@type':'Article' if article else 'WebPage','headline' if article else 'name':title,'description':desc,'url':ORIGIN+route,'image':ORIGIN+'/'+image}
 if article:schema.update(author={'@type':'Organization','name':'The Dreamer'},about={'@type':'Person','name':'Rabii Ben Brahim'})
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080808"><title>{e(title)} | The Dreamer</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{ORIGIN+route}"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:title" content="{e(title)} | The Dreamer"><meta property="og:description" content="{e(desc)}"><meta property="og:image" content="{ORIGIN+'/'+image}"><meta property="og:url" content="{ORIGIN+route}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/logo.png"><link rel="stylesheet" href="/editorial.css"><script type="application/ld+json">{json.dumps(schema)}</script><script defer src="/editorial.js"></script></head><body class="{'front-page' if route=='/' else 'inside-page'}"><a class="skip" href="#main">Skip to content</a><header class="publication-header"><a class="brand" href="/" aria-label="The Dreamer — home"><img src="/assets/logo.png" width="47" height="47" alt=""><span>THE DREAMER<span class="brand-sub">WILD & FREE</span></span></a><nav class="desktop-nav" aria-label="Main navigation">{nav}</nav><button id="menu-toggle" class="menu-toggle" aria-controls="publication-menu" aria-expanded="false">Menu <span aria-hidden="true">☰</span></button></header><dialog id="publication-menu" class="menu-dialog" aria-label="Explore The Dreamer"><div class="menu-top">{label('THE DREAMER / EXPLORE')}<button data-close aria-label="Close menu">Close ×</button></div><nav aria-label="Full navigation">{nav}</nav><div class="menu-secondary">{secondary}</div><p>Stories from the wild.<br>Rabii Ben Brahim.</p></dialog><main id="main">{body}</main><footer><div class="footer-top"><div>{label('THE DREAMER / RABII BEN BRAHIM')}<p class="footer-statement">Keep looking closer.</p><p>Wildlife. People. Place.<br>Film and photography from the field.</p></div><nav aria-label="Footer navigation">{secondary}</nav><div class="social-links">{link(IG,'Instagram','')}{link('https://www.youtube.com/@thedreamerwildandfree','YouTube','')}{link('https://www.linkedin.com/in/rabii-ben-brahim-007309141','LinkedIn','')}</div></div><div class="footer-bottom"><span>© 2026 THE DREAMER</span>{link('https://auradigitalworks.com/','Made by AuraDigital','')}{link('#main','Back to the beginning','')}</div></footer><dialog id="media-viewer" class="media-dialog" aria-label="Media viewer"><button class="viewer-close" data-close aria-label="Close viewer">Close ×</button><div id="viewer-content"></div><div class="viewer-navigation"><button id="photo-prev" aria-label="Previous photograph">←</button><p id="viewer-caption" aria-live="polite"></p><button id="photo-next" aria-label="Next photograph">→</button></div></dialog></body></html>'''
 path=ROOT/route.strip('/')/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(html);PAGES.append(route)
def intro(kicker,title,text):return f'<section class="page-intro wrap">{label(kicker)}<h1>{title}</h1><p>{text}</p></section>'
def sectionhead(kicker,title,url=None,cta='Explore all'):
 return f'<div class="section-heading"><div>{label(kicker)}<h2>{title}</h2></div>{link(url,cta) if url else ""}</div>'
def tile(s,large=False):
 return f'<article class="story-tile {"large-tile" if large else ""}"><a href="/stories/{s["slug"]}/">{img(s["image"],s["desc"])}{label(s["category"])}<h3>{s["title"]}</h3><p>{s["place"]} <span aria-hidden="true">↗</span></p></a></article>'
def filmcard(f,featured=False):
 slug,title,id,cat,path,desc=f
 return f'<article class="film-card {"featured-film" if featured else ""}"><a class="film-poster" href="/films/{slug}/" data-film="{id}" data-title="{title}">{img(path,desc)}<span class="play-mark" aria-hidden="true">▷</span><span class="film-overlay">{label(cat)}<strong>{title}</strong><span>WATCH FILM →</span></span></a></article>'
def photocard(n):
 title,alt,cat=PHOTO[n]
 return f'<figure class="photo-entry" data-category="{cat}"><a href="/{P(n)}" data-photo data-caption="{e(title)} — {e(cat)} · The Dreamer photo archive">{img(P(n),alt)}</a><figcaption><span>{title}</span><span>{cat}</span></figcaption></figure>'
def journeycard(slug,title,path,desc):
 return f'<article class="journey-card"><a href="/expeditions/{slug}/">{img(path,desc)}{label("FIELD JOURNEY / TUNISIA")}<h3>{title}</h3><p>{desc} <span aria-hidden="true">↗</span></p></a></article>'
